string minWindow(string s, string t) {
    // need[c] > 0 means we still owe that many c's. Extras go negative and are ignored.
    int need[128] = {};
    for (char c : t) need[(unsigned char)c]++;
    int missing = (int)t.size(); // counts duplicates, not distinct chars
    int best = INT_MAX, start = 0, left = 0;
    for (int right = 0; right < (int)s.size(); right++) {
        unsigned char c = s[right];
        if (need[c] > 0) missing--;
        need[c]--;
        while (missing == 0) { // window is valid — shrink it before moving on
            if (right - left + 1 < best) {
                best = right - left + 1;
                start = left;
            }
            unsigned char d = s[left++];
            need[d]++;
            if (need[d] > 0) missing++; // this char was required; window just broke
        }
    }
    return best == INT_MAX ? "" : s.substr(start, best);
}
// O(|s| + |t|) time, O(1) space — alphabet is fixed

vector<int> zeroSumSubarray(vector<int>& a) {
    // pref[j] == pref[i-1]  ⇒  a[i..j] sums to 0. Seed 0 at index -1 for a prefix that is itself 0.
    unordered_map<long long, int> first; // long long: n * 1e9 does not fit in 32 bits
    first[0] = -1;
    long long sum = 0;
    for (int i = 0; i < (int)a.size(); i++) {
        sum += a[i];
        auto it = first.find(sum);
        if (it != first.end())
            return vector<int>(a.begin() + it->second + 1, a.begin() + i + 1);
        first.emplace(sum, i); // keep the earliest index; any subarray is acceptable
    }
    return {};
}
// O(N) time, O(N) space

struct ListNode {
    int val;
    ListNode* next;
    ListNode() : val(0), next(nullptr) {}
    ListNode(int x) : val(x), next(nullptr) {}
};

ListNode* mergeKLists(vector<ListNode*>& lists) {
    // Min-heap of the current head of each list. Default priority_queue is a max-heap,
    // so the comparator is reversed.
    auto cmp = [](ListNode* a, ListNode* b) { return a->val > b->val; };
    priority_queue<ListNode*, vector<ListNode*>, decltype(cmp)> pq(cmp);
    for (ListNode* node : lists)
        if (node) pq.push(node);

    ListNode dummy; // dummy so the first real node needs no special case
    ListNode* tail = &dummy;
    while (!pq.empty()) {
        tail->next = pq.top();
        pq.pop();
        tail = tail->next;
        if (tail->next) pq.push(tail->next); // advance only the list we just took from
    }
    return dummy.next;
}
// O(N log K) time, O(K) heap space

int jump(vector<int>& nums) {
    // Implicit BFS: indices reachable in the same number of jumps are one layer.
    // curEnd is the end of this layer; farthest is how far the next layer reaches.
    int jumps = 0, curEnd = 0, farthest = 0;
    for (int i = 0; i < (int)nums.size() - 1; i++) {
        farthest = max(farthest, i + nums[i]);
        if (i == curEnd) {
            jumps++;
            curEnd = farthest;
        }
    }
    return jumps;
}
// O(N) time, O(1) space

// Follow-up: one shortest path of indexes. The node inside the layer that
// reaches farthest can also reach every newly opened index, because those
// indexes sit strictly to its right and within its reach.
vector<int> jumpWithPath(vector<int>& nums) {
    int n = (int)nums.size();
    if (n <= 1) return {0};
    vector<int> prev(n, -1);
    int left = 0, right = 0;
    while (right < n - 1) {
        int farthest = right, from = -1;
        for (int i = left; i <= right; i++) {
            int reach = min(n - 1, i + nums[i]);
            if (reach > farthest) {
                farthest = reach;
                from = i;
            }
        }
        if (from == -1) return {}; // this layer cannot move; unreachable
        for (int j = right + 1; j <= farthest; j++) prev[j] = from;
        left = right + 1;
        right = farthest;
    }
    vector<int> path;
    for (int i = n - 1; i != -1; i = prev[i]) path.push_back(i);
    reverse(path.begin(), path.end());
    return path;
}
// O(N) time, O(N) space

vector<vector<int>> merge(vector<vector<int>>& intervals) {
    sort(intervals.begin(), intervals.end()); // by start, then end
    vector<vector<int>> merged;
    for (auto& iv : intervals) {
        // Strict < so touching ends ([1,4] and [4,5]) are merged, as required.
        if (merged.empty() || merged.back()[1] < iv[0])
            merged.push_back(iv);
        else
            merged.back()[1] = max(merged.back()[1], iv[1]);
    }
    return merged;
}
// O(N log N) time, O(N) output space. After the sort, an overlap can only
// involve the interval we just emitted.

string multiply(string num1, string num2) {
    int m = (int)num1.size(), n = (int)num2.size();
    // Digit i (from the left) times digit j lands at positions i+j (carry) and i+j+1.
    vector<int> pos(m + n, 0);
    for (int i = m - 1; i >= 0; i--) {
        for (int j = n - 1; j >= 0; j--) {
            int sum = (num1[i] - '0') * (num2[j] - '0') + pos[i + j + 1];
            pos[i + j + 1] = sum % 10;
            pos[i + j] += sum / 10;
        }
    }
    string res;
    for (int d : pos)
        if (!(res.empty() && d == 0)) res.push_back('0' + d); // drop leading zeros
    return res.empty() ? "0" : res;
}
// O(M*N) time, O(M+N) space. Do not convert the inputs to an integer.

vector<pair<int,int>> pairsWithSum(vector<int>& a, vector<int>& b, int k) {
    // Count B, then walk every element of A. A set would collapse the two 1's in
    // A = [1,1,2], B = [3,4], K = 5 and drop a required pair.
    unordered_map<int, int> countB;
    for (int x : b) countB[x]++;
    vector<pair<int,int>> res;
    for (int av : a) {
        long long need = (long long)k - av; // values are ±1e9; subtract in 64 bits
        if (need < INT_MIN || need > INT_MAX) continue;
        int times = countB[(int)need];
        for (int t = 0; t < times; t++)
            res.push_back({av, (int)need});
    }
    return res;
}
// O(N + M + P) time, P = number of pairs. Output size can be N*M.

bool increasingTriplet(vector<int>& nums) {
    // first = smallest value so far.
    // second = smallest value that already has a strictly smaller value to its left.
    // A later number below `first` still updates `first`: it can only help a future
    // triplet, and `second` keeps the predecessor it already had.
    int first = INT_MAX, second = INT_MAX;
    for (int x : nums) {
        if (x <= first) first = x;          // <= so equals are not a strict increase
        else if (x <= second) second = x;
        else return true;                   // x is a third value above both
    }
    return false;
}
// O(N) time, O(1) space

int maxIndexDiff(vector<int>& arr) {
    int n = (int)arr.size();
    vector<int> lmin(n), rmax(n);
    lmin[0] = arr[0];
    for (int i = 1; i < n; i++) lmin[i] = min(lmin[i - 1], arr[i]);
    rmax[n - 1] = arr[n - 1];
    for (int j = n - 2; j >= 0; j--) rmax[j] = max(rmax[j + 1], arr[j]);

    // If the min on [0..i] is strictly below the max on [j..n-1], some pair
    // spanning at least j-i exists. Equals must not count: the problem is arr[j] > arr[i].
    int i = 0, j = 0, ans = -1;
    while (i < n && j < n) {
        if (lmin[i] < rmax[j]) {
            if (j > i) ans = max(ans, j - i);
            j++;
        } else {
            i++;
        }
    }
    return ans; // -1 when the array is non-increasing
}
// O(N) time, O(N) space

int maxScore(vector<int>& cards, int k) {
    int n = (int)cards.size();
    // There are only k+1 choices: take i cards from the right and k-i from the left.
    // Start with the left k, then trade the rightmost of those for the next card from the right.
    int window = 0;
    for (int i = 0; i < k; i++) window += cards[i];
    int best = window;
    for (int i = 0; i < k; i++) {
        window += cards[n - 1 - i] - cards[k - 1 - i];
        best = max(best, window);
    }
    return best;
}
// O(K) time, O(1) space. Sum fits in 32 bits under the constraints.

vector<int> frequencySort(vector<int>& nums) {
    unordered_map<int, int> freq;
    for (int x : nums) freq[x]++;
    sort(nums.begin(), nums.end(), [&](int a, int b) {
        if (freq[a] != freq[b]) return freq[a] > freq[b]; // higher frequency first
        return a < b;                                     // tie: smaller value first
    });
    return nums;
}
// O(N log N) time, O(N) space. The comparator is a strict weak order.

vector<int> searchRange(vector<int>& nums, int target) {
    auto bound = [&](bool lower) {
        int lo = 0, hi = (int)nums.size() - 1, ans = -1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (nums[mid] == target) {
                ans = mid;
                // Don't stop: another copy may sit further on this side.
                if (lower) hi = mid - 1;
                else lo = mid + 1;
            } else if (nums[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return ans;
    };
    if (nums.empty()) return {-1, -1};
    return {bound(true), bound(false)};
}
// O(log N) time, O(1) space. Two searches, not one.

ListNode* reverseKGroup(ListNode* head, int k) {
    ListNode dummy(0);
    dummy.next = head;
    ListNode* groupPrev = &dummy;
    while (true) {
        ListNode* kth = groupPrev;
        for (int i = 0; i < k && kth; i++) kth = kth->next;
        if (!kth) break; // leftover shorter than k stays in order

        ListNode* groupNext = kth->next;
        // Reverse this group. Starting prev at groupNext links the new tail for free.
        ListNode* prev = groupNext;
        ListNode* cur = groupPrev->next;
        while (cur != groupNext) {
            ListNode* nxt = cur->next;
            cur->next = prev;
            prev = cur;
            cur = nxt;
        }
        ListNode* newTail = groupPrev->next;
        groupPrev->next = kth;
        groupPrev = newTail;
    }
    return dummy.next;
}
// O(N) time, O(1) space. Prefer this over the recursive version (depth N/k).

struct Node {
    int val = 0;
    Node* next = nullptr;
    Node* random = nullptr;
};

// O(1) extra space besides the output. Three passes:
//   1. weave each copy in right after its original: A -> A' -> B -> B'
//   2. A'.random = A.random's copy, which is the node immediately after A.random
//   3. unweave the two lists
Node* copyRandomList(Node* head) {
    if (!head) return nullptr;
    for (Node* cur = head; cur; cur = cur->next->next) {
        Node* copy = new Node();
        copy->val = cur->val;
        copy->next = cur->next;
        cur->next = copy;
    }
    for (Node* cur = head; cur; cur = cur->next->next) {
        if (cur->random) cur->next->random = cur->random->next;
    }
    Node* copyHead = head->next;
    for (Node* cur = head; cur; cur = cur->next) {
        Node* copy = cur->next;
        cur->next = copy->next;
        copy->next = copy->next ? copy->next->next : nullptr;
    }
    return copyHead;
}
// O(N) time, O(1) extra space. A HashMap<Node*, Node*> is the version to
// write first if you are short on time; this is the follow-up they ask for.

struct Node { int val; Node *left, *right, *next; };

// Perfect tree: once a level's next pointers exist, walk that level and wire
// the level below. No queue. This is O(1) extra space, not O(height).
Node* connect(Node* root) {
    if (!root) return nullptr;
    Node* level = root;
    while (level->left) {
        for (Node* cur = level; cur; cur = cur->next) {
            cur->left->next = cur->right;
            if (cur->next) cur->right->next = cur->next->left; // cousin, not just sibling
        }
        level = level->left;
    }
    return root;
}
// O(N) time, O(1) extra space. A non-perfect tree (LC 117) cannot assume both children.

ListNode* getIntersectionNode(ListNode* a, ListNode* b) {
    // When a pointer hits the end, send it to the other head. The longer list's
    // extra prefix is walked exactly once, so both pointers then have the same
    // number of steps left and meet at the merge (or both become null).
    ListNode* pa = a;
    ListNode* pb = b;
    while (pa != pb) {
        pa = pa ? pa->next : b;
        pb = pb ? pb->next : a;
    }
    return pa;
}
// O(M + N) time, O(1) space

ListNode* reverseSecondHalf(ListNode* head) {
    if (!head || !head->next) return head;
    // slow stops on the last node of the first half (the middle, when the length is odd).
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast->next && fast->next->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    ListNode* prev = nullptr;
    ListNode* cur = slow->next;
    while (cur) {
        ListNode* nxt = cur->next;
        cur->next = prev;
        prev = cur;
        cur = nxt;
    }
    slow->next = prev;
    return head;
}
// O(N) time, O(1) space

struct TreeNode { int val; TreeNode *left, *right; };

// Both targets exist. A node that is p or q is the answer for its subtree:
// the other target is either here or the caller will combine the two sides.
TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
    if (!root || root == p || root == q) return root;
    TreeNode* left = lowestCommonAncestor(root->left, p, q);
    TreeNode* right = lowestCommonAncestor(root->right, p, q);
    if (left && right) return root; // p and q sit in different subtrees
    return left ? left : right;
}
// O(N) time, O(H) stack

// The "common manager" variant: employees point at their manager, not at children.
struct Emp { int id; Emp* manager; };

Emp* commonManager(Emp* a, Emp* b) {
    unordered_set<Emp*> seen;
    for (Emp* e = a; e; e = e->manager) seen.insert(e);
    for (Emp* e = b; e; e = e->manager)
        if (seen.count(e)) return e; // first hit is the deepest shared manager
    return nullptr;
}
// O(D) time and space, D = depth of the deeper employee

bool valid(TreeNode* node, long long lo, long long hi) {
    if (!node) return true;
    // Exclusive bounds. long long so a node holding INT_MIN / INT_MAX is still inside range.
    if (node->val <= lo || node->val >= hi) return false;
    return valid(node->left, lo, node->val) && valid(node->right, node->val, hi);
}

bool isValidBST(TreeNode* root) {
    return valid(root, LLONG_MIN, LLONG_MAX);
}
// O(N) time, O(H) stack. Inorder "previous value" is the other standard write-up.

vector<int> leftView(TreeNode* root) {
    vector<int> view;
    if (!root) return view;
    queue<TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
        int level = (int)q.size();
        for (int i = 0; i < level; i++) {
            TreeNode* node = q.front();
            q.pop();
            if (i == 0) view.push_back(node->val); // first node visited on this level
            if (node->left) q.push(node->left);
            if (node->right) q.push(node->right);
        }
    }
    return view;
}
// O(N) time, O(width) space. Push left before right or the "first" node is the right view.

vector<vector<int>> verticalOrder(TreeNode* root) {
    vector<vector<int>> order;
    if (!root) return order;
    map<int, vector<int>> cols; // column -> values, left to right
    queue<pair<TreeNode*, int>> q;
    q.push({root, 0});
    while (!q.empty()) {
        auto [node, col] = q.front();
        q.pop();
        // BFS visits a column top to bottom. Left is enqueued before right,
        // so two nodes on the same row stay left-to-right. Do not sort by value
        // unless they explicitly ask for the LeetCode 987 rule.
        cols[col].push_back(node->val);
        if (node->left) q.push({node->left, col - 1});
        if (node->right) q.push({node->right, col + 1});
    }
    for (auto& [col, vals] : cols) order.push_back(std::move(vals));
    return order;
}
// O(N log C) time, C = number of columns, O(N) space

bool pathExists(vector<vector<int>>& grid) {
    // 0 is open, 1 is a wall. Existence does not need backtracking:
    // the first time BFS reaches a cell is enough, so mark it visited and never return.
    int n = (int)grid.size(), m = (int)grid[0].size();
    if (grid[0][0] != 0 || grid[n - 1][m - 1] != 0) return false;
    vector<vector<char>> seen(n, vector<char>(m, 0));
    queue<pair<int, int>> q;
    q.push({0, 0});
    seen[0][0] = 1;
    const int d[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    while (!q.empty()) {
        auto [r, c] = q.front();
        q.pop();
        if (r == n - 1 && c == m - 1) return true;
        for (auto& dir : d) {
            int nr = r + dir[0], nc = c + dir[1];
            if (nr < 0 || nc < 0 || nr >= n || nc >= m) continue;
            if (seen[nr][nc] || grid[nr][nc] != 0) continue;
            seen[nr][nc] = 1;
            q.push({nr, nc});
        }
    }
    return false;
}
// O(NM) time and space. Backtracking (unmark on the way out) is only for listing every path,
// and that is exponential. n, m <= 100, so a recursive DFS would also fit, but BFS will not blow the stack.

int minCutDiff(int n, vector<vector<int>>& edges, vector<int>& values) {
    vector<vector<int>> adj(n);
    for (auto& e : edges) {
        adj[e[0]].push_back(e[1]);
        adj[e[1]].push_back(e[0]);
    }
    long long total = 0;
    for (int v : values) total += v; // values may be negative; the difference formula still holds

    long long best = LLONG_MAX;
    // sub(u) is the sum of u's component if we cut the edge up to parent.
    // The other component is total - sub, so the difference is |total - 2*sub|.
    // Skipping parent == -1: there is no edge above the root.
    function<long long(int, int)> dfs = [&](int u, int parent) -> long long {
        long long sub = values[u];
        for (int v : adj[u])
            if (v != parent) sub += dfs(v, u);
        if (parent != -1) best = min(best, llabs(total - 2 * sub));
        return sub;
    };
    dfs(0, -1);
    return (int)best;
}
// O(N) time, O(N) space. n >= 2, so some edge is always cut. Keep this state
// in locals — a file-scope `ans` breaks the next test case.

void tarjan(vector<vector<int>>& g, int u, int parent,
            vector<int>& disc, vector<int>& low,
            vector<vector<int>>& bridges, int& time) {
    disc[u] = low[u] = time++;
    for (int v : g[u]) {
        if (disc[v] == -1) {
            tarjan(g, v, u, disc, low, bridges, time);
            low[u] = min(low[u], low[v]);
            // v's subtree has no back edge to u or an ancestor of u, so u—v is a bridge.
            if (low[v] > disc[u]) bridges.push_back({u, v});
        } else if (v != parent) {
            low[u] = min(low[u], disc[v]); // back edge; use discovery time, not low[v]
        }
    }
}

vector<vector<int>> criticalConnections(int n, vector<vector<int>>& edges) {
    vector<vector<int>> g(n), bridges;
    vector<int> disc(n, -1), low(n);
    for (auto& e : edges) {
        g[e[0]].push_back(e[1]);
        g[e[1]].push_back(e[0]);
    }
    int time = 0; // local, not a global — a second call must start from zero
    for (int i = 0; i < n; i++)
        if (disc[i] == -1) tarjan(g, i, -1, disc, low, bridges, time);
    return bridges;
}
// O(V + E) time and space

vector<long long> dijkstra(vector<vector<pair<int, int>>>& g, int src) {
    int n = (int)g.size();
    const long long INF = LLONG_MAX / 4; // leave room for dist[u] + w
    vector<long long> dist(n, INF);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;
    dist[src] = 0;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u]) continue; // a better path to u was already finalized
        for (auto [v, w] : g[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }
    return dist;
}
// O((V + E) log V) time with a binary heap, O(V) extra space.
// Non-negative weights only. A negative edge means Bellman-Ford.

bool canReach(int x, int y) {
    // A move (a, b) -> (a+b, b) or (a, a+b) does not change gcd.
    // Running the move backwards is Euclidean subtraction, so (x, y)
    // reaches (1, 1) if and only if gcd(x, y) == 1.
    return __gcd(x, y) == 1;
}
// O(log min(x, y)) time, O(1) space

int maxSumIncreasing(vector<int>& arr) {
    int n = (int)arr.size();
    if (n == 0) return 0;
    // dp[i] = best increasing-subsequence sum that ends at i. Must include arr[i].
    vector<int> dp(arr.begin(), arr.end());
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (arr[j] < arr[i])
                dp[i] = max(dp[i], dp[j] + arr[i]);
        }
    }
    return *max_element(dp.begin(), dp.end());
}
// O(N^2) time, O(N) space. This is not LIS length — the values are the cost.

int longestConsecutive(vector<int>& nums) {
    unordered_set<int> have(nums.begin(), nums.end());
    int best = 0;
    for (int x : have) {
        if (have.count(x - 1)) continue; // only start at the beginning of a run
        int y = x, len = 1;
        while (have.count(++y)) len++;
        best = max(best, len);
    }
    return best;
}
// O(N) expected time: each number is the inner-loop cursor of exactly one run. O(N) space.

vector<string> permutations(string s) {
    sort(s.begin(), s.end()); // groups equal chars so the skip below is valid
    vector<string> out;
    string path;
    vector<char> used(s.size(), 0);
    function<void()> build = [&]() {
        if (path.size() == s.size()) {
            out.push_back(path);
            return;
        }
        for (int i = 0; i < (int)s.size(); i++) {
            if (used[i]) continue;
            // Same char as the previous one, and that previous one is unused:
            // this choice is a duplicate of a branch we already built.
            if (i > 0 && s[i] == s[i - 1] && !used[i - 1]) continue;
            used[i] = 1;
            path.push_back(s[i]);
            build();
            path.pop_back();
            used[i] = 0;
        }
    };
    build();
    return out;
}
// Distinct input: N! leaves. With duplicates the skip cuts the repeated branches.
// N <= 8, so the N factor from copying each string is fine.

long long diceWays(int dice, int faces, int target) {
    // dp[d][s] = ways to make sum s with d dice, each showing 1..faces.
    vector<vector<long long>> dp(dice + 1, vector<long long>(target + 1, 0));
    dp[0][0] = 1; // one way to make 0 with no dice
    for (int d = 1; d <= dice; d++) {
        for (int sum = d; sum <= target; sum++) { // d dice make at least d
            for (int face = 1; face <= faces && face <= sum; face++)
                dp[d][sum] += dp[d - 1][sum - face];
        }
    }
    return dp[dice][target];
}
// O(dice * target * faces) time, O(dice * target) space.
// A rolling 1D array drops the space to O(target) if they ask.

vector<string> generateParenthesis(int n) {
    vector<string> out;
    string cur;
    function<void(int, int)> build = [&](int open, int close) {
        if ((int)cur.size() == 2 * n) {
            out.push_back(cur);
            return;
        }
        if (open < n) {
            cur.push_back('(');
            build(open + 1, close);
            cur.pop_back();
        }
        if (close < open) { // a close is only legal while it does not outnumber opens
            cur.push_back(')');
            build(open, close + 1);
            cur.pop_back();
        }
    };
    build(0, 0);
    return out;
}
// Catalan number of strings. Passing the string by reference avoids copying it on every call.

string longestRepeating(string s) {
    int n = (int)s.size();
    // dp[i][j] = length of a repeated substring ending at s[i-1] and at s[j-1].
    vector<vector<int>> dp(n + 1, vector<int>(n + 1, 0));
    int best = 0, end = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = i + 1; j <= n; j++) {
            if (s[i - 1] != s[j - 1]) continue;
            // The match so far must be shorter than the gap between the two ends,
            // otherwise the two copies overlap.
            if (dp[i - 1][j - 1] >= j - i) continue;
            dp[i][j] = dp[i - 1][j - 1] + 1;
            if (dp[i][j] > best) {
                best = dp[i][j];
                end = i - 1;
            }
        }
    }
    if (best == 0) return "";
    return s.substr(end - best + 1, best);
}
// O(N^2) time and space. N <= 500, so this is the expected solution.

class FreqStack {
    unordered_map<int, int> freq;
    // group[f] holds the values whose *current* frequency is f, most recent at the back.
    // Popping the most frequent, then the most recent, is just the back of group[maxFreq].
    unordered_map<int, vector<int>> group;
    int maxFreq = 0;
public:
    void push(int x) {
        int f = ++freq[x];
        group[f].push_back(x);
        maxFreq = max(maxFreq, f);
    }
    int pop() {
        int x = group[maxFreq].back();
        group[maxFreq].pop_back();
        freq[x]--;
        if (group[maxFreq].empty()) maxFreq--;
        return x;
    }
};
// push and pop are O(1) amortized. Space O(N).

int findKthLargest(vector<int>& nums, int k) {
    // Min-heap of the k largest seen so far. The top is the smallest of those, i.e. the kth largest.
    priority_queue<int, vector<int>, greater<int>> heap;
    for (int x : nums) {
        heap.push(x);
        if ((int)heap.size() > k) heap.pop();
    }
    return heap.top();
}
// O(N log K) time, O(K) space.
// Follow-up: quickselect is O(N) average, O(N^2) worst. The heap is what you write first.

class LRUCache {
    int cap;
    // Front is most recently used, back is the eviction candidate.
    list<pair<int, int>> order;
    unordered_map<int, list<pair<int, int>>::iterator> pos;
public:
    explicit LRUCache(int capacity) : cap(capacity) {}

    int get(int key) {
        auto it = pos.find(key);
        if (it == pos.end()) return -1;
        order.splice(order.begin(), order, it->second); // O(1) move to front
        return it->second->second;
    }

    void put(int key, int value) {
        auto it = pos.find(key);
        if (it != pos.end()) {
            order.erase(it->second); // update must not evict a different key
        } else if ((int)order.size() == cap) {
            pos.erase(order.back().first);
            order.pop_back();
        }
        order.push_front({key, value});
        pos[key] = order.begin();
    }
};
// get and put O(1) average. A map ordered by timestamp is O(log N) and fails the requirement.

class MyStack {
    queue<int> q;
public:
    void push(int x) { // O(N): rotate so x sits at the front and pop stays O(1)
        q.push(x);
        for (int i = 0; i < (int)q.size() - 1; i++) {
            q.push(q.front());
            q.pop();
        }
    }
    int pop() { int x = q.front(); q.pop(); return x; } // O(1)
    int top() { return q.front(); }
    bool empty() { return q.empty(); }
};

class MyQueue {
    stack<int> in, out;
    void pour() { // O(N) once, then the next pops are O(1) — amortized O(1)
        if (out.empty()) {
            while (!in.empty()) {
                out.push(in.top());
                in.pop();
            }
        }
    }
public:
    void push(int x) { in.push(x); } // O(1)
    int pop() { pour(); int x = out.top(); out.pop(); return x; }
    int peek() { pour(); return out.top(); }
    bool empty() { return in.empty() && out.empty(); }
};

import java.util.Arrays;

/**
 * Separate chaining, power-of-two capacity, rehash at load 0.75.
 * Methods are synchronized: correct, and the answer to "make put thread-safe".
 * The follow-up is striped locks (one monitor per bucket). Resize then has to
 * take every stripe, or a single resize lock, or the two puts race on the table.
 * A global lock is what you code; stripes are what you discuss.
 */
class MyHashMap {
    private static final class Node {
        final int key;
        int val;
        Node next;
        Node(int key, int val, Node next) {
            this.key = key;
            this.val = val;
            this.next = next;
        }
    }

    private Node[] table = new Node[16]; // 16 so the first mask is 4 bits; must stay a power of two
    private int size = 0;

    public synchronized void put(int key, int val) {
        int i = index(key, table.length);
        for (Node n = table[i]; n != null; n = n.next) {
            if (n.key == key) { n.val = val; return; } // update, do not grow size
        }
        table[i] = new Node(key, val, table[i]);
        if (++size > table.length * 3 / 4) resize();
    }

    public synchronized Integer get(int key) {
        for (Node n = table[index(key, table.length)]; n != null; n = n.next)
            if (n.key == key) return n.val;
        return null;
    }

    public synchronized void remove(int key) {
        int i = index(key, table.length);
        Node prev = null;
        for (Node n = table[i]; n != null; n = n.next) {
            if (n.key == key) {
                if (prev == null) table[i] = n.next;
                else prev.next = n.next;
                size--;
                return;
            }
            prev = n;
        }
    }

    private void resize() {
        Node[] bigger = new Node[table.length << 1];
        for (Node head : table) {
            for (Node n = head; n != null; n = n.next) {
                int i = index(n.key, bigger.length);
                bigger[i] = new Node(n.key, n.val, bigger[i]);
            }
        }
        table = bigger;
    }

    // Bitmask, not %. Java's % on a negative hash is negative and is not a bucket index.
    private static int index(int key, int cap) {
        int h = key ^ (key >>> 16);
        return h & (cap - 1);
    }
}

