class HtmlWordCounter {
    private final ExecutorService pool;

    HtmlWordCounter(int threads) {
        // Do not call supplyAsync() with no executor. That uses the common ForkJoinPool,
        // and a blocked HTTP read pins a worker the rest of the JVM also needs.
        this.pool = Executors.newFixedThreadPool(threads);
    }

    List<Hit> countAll(List<String> urls, String keyword) {
        List<CompletableFuture<Hit>> jobs = new ArrayList<>();
        for (String url : urls)
            jobs.add(CompletableFuture.supplyAsync(() -> countOne(url, keyword), pool));
        List<Hit> out = new ArrayList<>();
        for (CompletableFuture<Hit> job : jobs) out.add(job.join());
        return out;
    }

    private Hit countOne(String url, String keyword) {
        try {
            return new Hit(url, keyword, occurrences(fetchHtml(url), keyword));
        } catch (Exception failed) {
            return new Hit(url, keyword, -1); // one bad URL must not fail the batch
        }
    }

    static long occurrences(String text, String keyword) {
        if (keyword.isEmpty()) return 0;
        long n = 0;
        for (int from = 0; from <= text.length() - keyword.length(); ) {
            int at = text.indexOf(keyword, from);
            if (at < 0) break;
            n++;
            from = at + keyword.length(); // non-overlapping
        }
        return n;
    }

    /** HTTP GET. Anything thrown here becomes count -1. */
    String fetchHtml(String url) throws Exception {
        throw new UnsupportedOperationException(url);
    }

    record Hit(String url, String keyword, long count) {}
}

import java.util.concurrent.atomic.AtomicReference;

/**
 * Two threads must be able to set different fields and both writes must survive.
 * A setter that returns a new builder to its caller does not publish that write
 * to the other thread, so it fails the shared-builder case.
 * The shared state is an immutable snapshot. CAS swaps the whole snapshot;
 * a lost race retries and copies the field the other thread just published.
 */
final class ConfigBuilder {
    static final class Config {
        final String name;
        final String role;
        Config(String name, String role) {
            this.name = name;
            this.role = role;
        }
    }

    private final AtomicReference<Config> ref =
            new AtomicReference<>(new Config(null, null));

    void setName(String name) {
        Config cur, next;
        do {
            cur = ref.get();
            next = new Config(name, cur.role); // keep the role we just observed
        } while (!ref.compareAndSet(cur, next));
    }

    void setRole(String role) {
        Config cur, next;
        do {
            cur = ref.get();
            next = new Config(cur.name, role);
        } while (!ref.compareAndSet(cur, next));
    }

    Config build() {
        return ref.get(); // immutable, so the caller cannot observe a torn pair of fields
    }
}

