int findUnsortedSubarray(vector<int>& nums) {
    int n = (int)nums.size();
    int right = -1, maxSoFar = INT_MIN;
    for (int i = 0; i < n; i++) {
        maxSoFar = max(maxSoFar, nums[i]);
        if (nums[i] < maxSoFar) right = i; // i is out of order relative to the prefix
    }
    int left = n, minSoFar = INT_MAX;
    for (int i = n - 1; i >= 0; i--) {
        minSoFar = min(minSoFar, nums[i]);
        if (nums[i] > minSoFar) left = i;
    }
    return right == -1 ? 0 : right - left + 1;
}
// O(N) time, O(1) space. Sorting a copy and comparing is the O(N log N) answer
