int josephus(int n, int k) {
    // 0-based: f(1) = 0, f(i) = (f(i-1) + k) % i.
    // After the first person is removed, the next count starts at the next seat,
    // which is a rotation of an (i-1)-person problem.
    int pos = 0;
    for (int i = 2; i <= n; i++) pos = (pos + k) % i;
    return pos + 1; // the prompt numbers people from 1
}
