int totalJumps(vector<int>& walls, int H, int L) {
    // One failed attempt gains H then loses L. The last jump does not slip.
    // So a wall of height w <= H is one jump, and a taller wall needs
    //   failed = ceil((w - H) / (H - L))
    //   jumps  = failed + 1.
    // Simulating the climb is the same answer and is too slow when H - L is 1 and w is 1e5.
    long long jumps = 0;
    long long gain = (long long)H - L;
    for (int w : walls) {
        if (w <= H) { jumps++; continue; }
        if (gain <= 0) return -1; // no net progress, and this wall is taller than one jump
        long long failed = ((long long)w - H + gain - 1) / gain;
        jumps += failed + 1;
    }
    return (int)jumps;
}
// O(N) time, O(1) space

bool isOpen(const vector<int>& open, const vector<int>& close, int t) {
    // Intervals may overlap and are not sorted, and n <= 100, so scan.
    // Half-open: t == open[i] is inside, t == close[i] is not.
    // Binary search on open[] is wrong here — overlapping intervals do not
    // have a single "the interval that contains t".
    for (int i = 0; i < (int)open.size(); i++) {
        if (t >= open[i] && t < close[i]) return true;
